	regionKind = "place",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[Marshal's Refuge is a camp of tents and cooking fires set among the rocks of the crater's northern wall. It was founded in flight. When the beasts of {link:un-goro-crater}Un'Goro{/link} overran the camps of Marshal Expeditions, {link:williden-marshal}Williden Marshal{/link} and his people climbed to this high ground, where the great saurians could not easily follow. Others have since joined them: a flight master of {link:gadgetzan}Gadgetzan{/link}, lost wanderers, quarrelling travellers and a student of crystals who works in the cave above the camp. The refuge is the only place in the crater where a traveller may sleep without keeping one eye open.]=],
		},
	},
})

