	sections = {
		{
			title = "Summary",
			text = [=[Three pylons of crystal stand in the wilds of {link:un-goro-crater}Un'Goro Crater{/link}: one in the north, one against the eastern wall and one in the west. They are tall works of stone lined inside with crystal, and they are far older than the camp of any living explorer. For a long time they were only rumors told at {link:marshal-s-refuge}Marshal's Refuge{/link}.]=],
		},
		{
			title = "The Crystals",
			text = [=[Colored crystals lie scattered across the crater floor: red, blue, yellow and green. Most travellers ignore them. The {link:gnomes}gnome{/link} {link:j-d-collie}J.D. Collie{/link} did not. She gathered them by the sackful and tried every combination she could think of, but they gave up nothing until the pylons were found. Once travellers had examined all three, she worked through what they had seen and wrote her findings in a manual. With it, the crystals could be fused into combinations that restore, strengthen, ward and charge those who carry them.]=],
		},
		{
			title = "Unanswered",
			text = [=[Who raised the pylons, and to what end, the crater does not say. {link:j-d-collie}J.D. Collie{/link} learned how to use their crystals. She did not learn why they were there.]=],
		},
	},
})

