			title = "Summary",
			text = [=[Linken is a {link:gnomes}gnome{/link} who arrived in {link:un-goro-crater}Un'Goro Crater{/link} with no memory of who he was or why he had come. He knows only that something important brought him here. Unlike most of his people, he has no interest in gadgets. {link:j-d-collie}J.D. Collie{/link} suspects that he is a warrior at heart.]=],
		},
